<?php
namespace App\Http\Controllers; use App\Models\{Order,Payment,Ticket}; use Illuminate\Support\Facades\DB;
class AdminReportController extends Controller {public function sales(){return view('admin.reports.sales',['summary'=>['sales'=>Order::where('status','paid')->sum('total'),'orders'=>Order::where('status','paid')->count(),'tickets'=>Ticket::where('status','valid')->count(),'refunds'=>Payment::where('status','refunded')->sum('amount')],'daily'=>Order::selectRaw('date(created_at) as day, count(*) as orders, sum(total) as amount')->where('status','paid')->groupBy('day')->latest('day')->limit(31)->get()]);}public function orders(){return view('admin.orders.index',['orders'=>Order::with('show.event','show.venue')->latest()->paginate(25)]);}public function refund(Order $order){abort_unless($order->status==='paid',422,'سفارش قابل استرداد نیست.');$order->update(['status'=>'refunded']);$order->tickets()->update(['status'=>'refunded']);$order->payments()->where('status','paid')->update(['status'=>'refunded']);return back()->with('success','سفارش مسترد شد.');}}
